import{_ as p,a0 as o,w as d,s as u,I as a,x as n,a1 as t,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 Cloud-init 將節點添加到你的私有云中 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Cloud-init 將節點添加到你的私有云中 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Cloud-init 將節點添加到你的私有云中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Cloud-init 將節點添加到你的私有云中 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200527 Add nodes to your private cloud using Cloud-init","title":"使用 Cloud-init 將節點添加到你的私有云中","tag":"202007","desc":""},"relativePath":"202007/20200527 Add nodes to your private cloud using Cloud-init.md","filePath":"[post].md"}'),r={name:"202007/20200527 Add nodes to your private cloud using Cloud-init.md"};function c(g,s,h,b,k,f){const i=o("Link");return d(),u("div",null,[s[44]||(s[44]=a("h1",{id:"使用-cloud-init-將節點添加到你的私有云中",tabindex:"-1"},[n("使用 Cloud-init 將節點添加到你的私有云中 "),a("a",{class:"header-anchor",href:"#使用-cloud-init-將節點添加到你的私有云中","aria-label":"Permalink to “使用 Cloud-init 將節點添加到你的私有云中”"},"​")],-1)),s[45]||(s[45]=a("blockquote",null,[a("p",null,"像主流雲提供商的處理方式一樣，在家中添加機器到你的私有云。")],-1)),s[46]||(s[46]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202007/12/100823rj096h3ax4hhehey.jpg",alt:""})],-1)),a("p",null,[t(i,{href:"https://cloudinit.readthedocs.io/"},{default:e(()=>[...s[0]||(s[0]=[n("Cloud-init",-1)])]),_:1}),s[2]||(s[2]=n(" 是一種廣泛使用的行業標準方法，用於初始化雲實例。雲提供商使用 Cloud-init 來定製實例的網絡配置、實例信息，甚至用户提供的配置指令。它也是一個可以在你的“家庭私有云”中使用的很好的工具，可以為你的家庭實驗室的虛擬機和物理機的初始設置和配置添加一點自動化 —— 並瞭解更多關於大型雲提供商是如何工作的信息。關於更多的細節和背景，請看我之前的文章《",-1)),t(i,{href:"https://linux.cn/article-12371-1.html"},{default:e(()=>[...s[1]||(s[1]=[n("在你的樹莓派家庭實驗室中使用 Cloud-init",-1)])]),_:1}),s[3]||(s[3]=n("》。",-1))]),s[47]||(s[47]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/uploads/cloud-init.jpg",alt:"A screen showing the boot process for a Linux server running Cloud-init ",title:"A screen showing the boot process for a Linux server running Cloud-init "})],-1)),a("p",null,[a("em",null,[s[5]||(s[5]=n("運行 Cloud-init 的 Linux 服務器的啓動過程（Chris Collins，",-1)),t(i,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:e(()=>[...s[4]||(s[4]=[n("CC BY-SA 4.0",-1)])]),_:1}),s[6]||(s[6]=n("）",-1))])]),s[48]||(s[48]=a("p",null,"誠然，Cloud-init 對於為許多不同客户配置機器的雲提供商來説，比對於由單個系統管理員運行的家庭實驗室更有用，而且 Cloud-init 解決的許多問題對於家庭實驗室來説可能有點多餘。然而，設置它並瞭解它的工作原理是瞭解更多關於這種雲技術的好方法，更不用説它是首次啓動時配置設備的好方法。",-1)),s[49]||(s[49]=a("p",null,"本教程使用 Cloud-init 的 NoCloud 數據源，它允許 Cloud-init 在傳統的雲提供商環境之外使用。本文將向你展示如何在客户端設備上安裝 Cloud-init，並設置一個運行 Web 服務的容器來響應客户端的請求。你還將學習如何審查客户端從 Web 服務中請求的內容，並修改 Web 服務的容器，以提供基本的、靜態的 Cloud-init 服務。",-1)),s[50]||(s[50]=a("h3",{id:"在現有系統上設置-cloud-init",tabindex:"-1"},[n("在現有系統上設置 Cloud-init "),a("a",{class:"header-anchor",href:"#在現有系統上設置-cloud-init","aria-label":"Permalink to “在現有系統上設置 Cloud-init”"},"​")],-1)),a("p",null,[s[8]||(s[8]=n("Cloud-init 可能在新系統首次啓動時最有用，它可以查詢配置數據，並根據指令對系統進行定製。它可以",-1)),t(i,{href:"https://linux.cn/article-12277-1.html"},{default:e(()=>[...s[7]||(s[7]=[n("包含在樹莓派和單板計算機的磁盤鏡像中",-1)])]),_:1}),s[9]||(s[9]=n("，也可以添加到用於",-1)),s[10]||(s[10]=a("ruby",null,[n("配給"),a("rt",null,"provision")],-1)),s[11]||(s[11]=n("虛擬機的鏡像中。對於測試用途來説，無論是在現有系統上安裝並運行 Cloud-init，還是安裝一個新系統，然後設置 Cloud-init，都是很容易的。",-1))]),s[51]||(s[51]=l(`<p>作為大多數雲提供商使用的主要服務，大多數 Linux 發行版都支持 Cloud-init。在這個例子中，我將使用 Fedora 31 Server 來安裝樹莓派，但在 Raspbian、Ubuntu、CentOS 和大多數其他發行版上也可以用同樣的方式來完成。</p><h4 id="安裝並啓用雲計算初始服務" tabindex="-1">安裝並啓用雲計算初始服務 <a class="header-anchor" href="#安裝並啓用雲計算初始服務" aria-label="Permalink to “安裝並啓用雲計算初始服務”">​</a></h4><p>在你想作為 Cloud-init 客户端的系統上，安裝 Cloud-init 包。如果你使用的是 Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Install the cloud-init package</span></span>
<span class="line"><span>dnf install -y cloud-init</span></span></code></pre></div><p>Cloud-init 實際上是四個不同的服務（至少在 systemd 下是這樣），這些服務負責檢索配置數據，並在啓動過程的不同階段進行配置更改，這使得可以做的事情更加靈活。雖然你不太可能直接與這些服務進行太多交互，但在你需要排除一些故障時，知道它們是什麼還是很有用的。它們是：</p><ul><li>cloud-init-local.service</li><li>cloud-init.service</li><li>cloud-config.service</li><li>cloud-final.service</li></ul><p>啓用所有四個服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Enable the four cloud-init services</span></span>
<span class="line"><span>systemctl enable cloud-init-local.service</span></span>
<span class="line"><span>systemctl enable cloud-init.service</span></span>
<span class="line"><span>systemctl enable cloud-config.service</span></span>
<span class="line"><span>systemctl enable cloud-final.service</span></span></code></pre></div><h4 id="配置數據源以查詢" tabindex="-1">配置數據源以查詢 <a class="header-anchor" href="#配置數據源以查詢" aria-label="Permalink to “配置數據源以查詢”">​</a></h4>`,9)),a("p",null,[s[13]||(s[13]=n("啓用服務後，請配置數據源，客户端將從該數據源查詢配置數據。有",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/datasources.html"},{default:e(()=>[...s[12]||(s[12]=[n("許多數據源類型",-1)])]),_:1}),s[14]||(s[14]=n("，而且大多數都是為特定的雲提供商配置的。對於你的家庭實驗室，請使用 NoCloud 數據源，（如上所述）它是為在沒有云提供商的情況下使用 Cloud-init 而設計的。",-1))]),s[52]||(s[52]=l(`<p>NoCloud 允許以多種方式包含配置信息：以內核參數中的鍵/值對，用於在啓動時掛載的 CD（或虛擬機中的虛擬 CD）；包含在文件系統中的文件中；或者像本例中一樣，通過 HTTP 從指定的 URL（“NoCloud Net” 選項）獲取配置信息。</p><p>數據源配置可以通過內核參數提供，也可以在 Cloud-init 配置文件 <code>/etc/cloud/cloud.cfg</code> 中進行設置。該配置文件對於使用自定義磁盤鏡像設置 Cloud-init 或在現有主機上進行測試非常方便。</p><p>Cloud-init 還會合並在 <code>/etc/cloud/cloud.cfg.d/</code> 中找到的任何 <code>*.cfg</code> 文件中的配置數據，因此為了保持整潔，請在 <code>/etc/cloud/cloud.cfg.d/10_datasource.cfg</code> 中配置數據源。Cloud-init 可以通過使用以下語法從 <code>seedfrom</code> 鍵指向的 HTTP 數據源中讀取數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>seedfrom: http://ip_address:port/</span></span></code></pre></div><p>IP 地址和端口是你將在本文後面創建的 Web 服務。我使用了我的筆記本電腦的 IP 和 8080 端口。這也可以是 DNS 名稱。</p><p>創建 <code>/etc/cloud/cloud.cfg.d/10_datasource.cfg</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Add the datasource:</span></span>
<span class="line"><span># /etc/cloud/cloud.cfg.d/10_datasource.cfg</span></span>
<span class="line"><span></span></span>
<span class="line"><span># NOTE THE TRAILING SLASH HERE!</span></span>
<span class="line"><span>datasource:</span></span>
<span class="line"><span>  NoCloud:</span></span>
<span class="line"><span>    seedfrom: http://ip_address:port/</span></span></code></pre></div><p>客户端設置就是這樣。現在，重新啓動客户端後，它將嘗試從你在 <code>seedfrom</code> 鍵中輸入的 URL 檢索配置數據，並進行必要的任何配置更改。</p><p>下一步是設置一個 Web 服務器來偵聽客户端請求，以便你確定需要提供的服務。</p><h3 id="設置網絡服務器以審查客户請求" tabindex="-1">設置網絡服務器以審查客户請求 <a class="header-anchor" href="#設置網絡服務器以審查客户請求" aria-label="Permalink to “設置網絡服務器以審查客户請求”">​</a></h3>`,10)),a("p",null,[s[16]||(s[16]=n("你可以使用 ",-1)),t(i,{href:"https://podman.io/"},{default:e(()=>[...s[15]||(s[15]=[n("Podman",-1)])]),_:1}),s[17]||(s[17]=n(" 或其他容器編排工具（如 Docker 或 Kubernetes）快速創建和運行 Web 服務器。這個例子使用的是 Podman，但同樣的命令也適用於 Docker。",-1))]),s[53]||(s[53]=l(`<p>要開始，請使用 <code>fedora:31</code> 容器鏡像並創建一個容器文件（對於 Docker 來説，這會是一個 Dockerfile）來安裝和配置 Nginx。從該容器文件中，你可以構建一個自定義鏡像，並在你希望提供 Cloud-init 服務的主機上運行它。</p><p>創建一個包含以下內容的容器文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM fedora:31</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ENV NGINX_CONF_DIR &quot;/etc/nginx/default.d&quot;</span></span>
<span class="line"><span>ENV NGINX_LOG_DIR &quot;/var/log/nginx&quot;</span></span>
<span class="line"><span>ENV NGINX_CONF &quot;/etc/nginx/nginx.conf&quot;</span></span>
<span class="line"><span>ENV WWW_DIR &quot;/usr/share/nginx/html&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Install Nginx and clear the yum cache</span></span>
<span class="line"><span>RUN dnf install -y nginx \\</span></span>
<span class="line"><span>      &amp;&amp; dnf clean all \\</span></span>
<span class="line"><span>      &amp;&amp; rm -rf /var/cache/yum</span></span>
<span class="line"><span></span></span>
<span class="line"><span># forward request and error logs to docker log collector</span></span>
<span class="line"><span>RUN ln -sf /dev/stdout \${NGINX_LOG_DIR}/access.log \\</span></span>
<span class="line"><span>    &amp;&amp; ln -sf /dev/stderr \${NGINX_LOG_DIR}/error.log</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Listen on port 8080, so root privileges are not required for podman</span></span>
<span class="line"><span>RUN sed -i -E &#39;s/(listen)([[:space:]]*)(\\[\\:\\:\\]\\:)?80;$/\\1\\2\\38080 default_server;/&#39; $NGINX_CONF</span></span>
<span class="line"><span>EXPOSE 8080</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow Nginx PID to be managed by non-root user</span></span>
<span class="line"><span>RUN sed -i &#39;/user nginx;/d&#39; $NGINX_CONF</span></span>
<span class="line"><span>RUN sed -i &#39;s/pid \\/run\\/nginx.pid;/pid \\/tmp\\/nginx.pid;/&#39; $NGINX_CONF</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run as an unprivileged user</span></span>
<span class="line"><span>USER 1001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CMD [&quot;nginx&quot;, &quot;-g&quot;, &quot;daemon off;&quot;]</span></span></code></pre></div>`,3)),a("p",null,[s[19]||(s[19]=n("注：本例中使用的容器文件和其他文件可以在本項目的 ",-1)),t(i,{href:"https://github.com/clcollins/homelabCloudInit/tree/master/simpleCloudInitService/data"},{default:e(()=>[...s[18]||(s[18]=[n("GitHub 倉庫",-1)])]),_:1}),s[20]||(s[20]=n("中找到。",-1))]),s[54]||(s[54]=l(`<p>上面容器文件中最重要的部分是改變日誌存儲方式的部分（寫到 STDOUT 而不是文件），這樣你就可以在容器日誌中看到進入該服務器的請求。其他的一些改變使你可以在沒有 root 權限的情況下使用 Podman 運行容器，也可以在沒有 root 權限的情況下運行容器中的進程。</p><p>在 Web 服務器上的第一個測試並不提供任何 Cloud-init 數據；只是用它來查看 Cloud-init 客户端的請求。</p><p>創建容器文件後，使用 Podman 構建並運行 Web 服務器鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build the container image</span></span>
<span class="line"><span>$ podman build -f Containerfile -t cloud-init:01 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Create a container from the new image, and run it</span></span>
<span class="line"><span># It will listen on port 8080</span></span>
<span class="line"><span>$ podman run --rm -p 8080:8080 -it cloud-init:01</span></span></code></pre></div><p>這會運行一個容器，讓你的終端連接到一個偽 TTY。一開始看起來什麼都沒有發生，但是對主機 8080 端口的請求會被路由到容器內的 Nginx 服務器，並且在終端窗口中會出現一條日誌信息。這一點可以用主機上的 <code>curl</code> 命令進行測試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Use curl to send an HTTP request to the Nginx container</span></span>
<span class="line"><span>$ curl http://localhost:8080</span></span></code></pre></div><p>運行該 <code>curl</code> 命令後，你應該會在終端窗口中看到類似這樣的日誌信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:19:25:10 +0000] &quot;GET / HTTP/1.1&quot; 200 5564 &quot;-&quot; &quot;curl/7.66.0&quot; &quot;-&quot;</span></span></code></pre></div><p>現在，有趣的部分來了：重啓 Cloud-init 客户端，並觀察 Nginx 日誌，看看當客户端啓動時， Cloud-init 向 Web 服務器發出了什麼請求。</p><p>當客户端完成其啓動過程時，你應該會看到類似的日誌消息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2020/05/09 22:44:28 [error] 2#0: *4 open() &quot;/usr/share/nginx/html/meta-data&quot; failed (2: No such file or directory), client: 127.0.0.1, server: _, request: &quot;GET /meta-data HTTP/1.1&quot;, host: &quot;instance-data:8080&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:22:44:28 +0000] &quot;GET /meta-data HTTP/1.1&quot; 404 3650 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span></code></pre></div><p>注：使用 <code>Ctrl+C</code> 停止正在運行的容器。</p><p>你可以看到請求是針對 <code>/meta-data</code> 路徑的，即 <code>http://ip_address_of_the_webserver:8080/meta-data</code>。這只是一個 GET 請求 —— Cloud-init 並沒有向 Web 服務器發送任何數據。它只是盲目地從數據源 URL 中請求文件，所以要由數據源來識別主機的要求。這個簡單的例子只是向任何客户端發送通用數據，但一個更大的家庭實驗室應該需要更復雜的服務。</p>`,13)),a("p",null,[s[22]||(s[22]=n("在這裏，Cloud-init 請求的是",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/instancedata.html#what-is-instance-data"},{default:e(()=>[...s[21]||(s[21]=[n("實例元數據",-1)])]),_:1}),s[23]||(s[23]=n("信息。這個文件可以包含很多關於實例本身的信息，例如實例 ID、分配實例的主機名、雲 ID，甚至網絡信息。",-1))]),s[55]||(s[55]=l(`<p>創建一個包含實例 ID 和主機名的基本元數據文件，並嘗試將其提供給 Cloud-init 客户端。</p><p>首先，創建一個可複製到容器鏡像中的 <code>meta-data</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>instance-id: iid-local01</span></span>
<span class="line"><span>local-hostname: raspberry</span></span>
<span class="line"><span>hostname: raspberry</span></span></code></pre></div><p>實例 ID（<code>instance-id</code>）可以是任何東西。但是，如果你在 Cloud-init 運行後更改實例 ID，並且文件被送達客户端，就會觸發 Cloud-init 再次運行。你可以使用這種機制來更新實例配置，但你應該意識到它是這種工作方式。</p><p><code>local-hostname</code> 和 <code>hostname</code> 鍵正如其名，它們會在 Cloud-init 運行時為客户端設置主機名信息。</p><p>在容器文件中添加以下行以將 <code>meta-data</code> 文件複製到新鏡像中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Copy the meta-data file into the image for Nginx to serve it</span></span>
<span class="line"><span>COPY meta-data \${WWW_DIR}/meta-data</span></span></code></pre></div><p>現在，用元數據文件重建鏡像（使用一個新的標籤以方便故障排除），並用 Podman 創建並運行一個新的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build a new image named cloud-init:02</span></span>
<span class="line"><span>podman build -f Containerfile -t cloud-init:02 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run a new container with this new meta-data file</span></span>
<span class="line"><span>podman run --rm -p 8080:8080 -it cloud-init:02</span></span></code></pre></div><p>新容器運行後，重啓 Cloud-init 客户端，再次觀察 Nginx 日誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:22:54:32 +0000] &quot;GET /meta-data HTTP/1.1&quot; 200 63 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span>
<span class="line"><span>2020/05/09 22:54:32 [error] 2#0: *2 open() &quot;/usr/share/nginx/html/user-data&quot; failed (2: No such file or directory), client: 127.0.0.1, server: _, request: &quot;GET /user-data HTTP/1.1&quot;, host: &quot;instance-data:8080&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:22:54:32 +0000] &quot;GET /user-data HTTP/1.1&quot; 404 3650 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span></code></pre></div><p>你看，這次 <code>/meta-data</code> 路徑被提供給了客户端。成功了！</p><p>然而，客户端接着在 <code>/user-data</code> 路徑上尋找第二個文件。該文件包含實例所有者提供的配置數據，而不是來自雲提供商的數據。對於一個家庭實驗室來説，這兩個都是你自己提供的。</p>`,13)),a("p",null,[s[25]||(s[25]=n("你可以使用",-1)),t(i,{href:"https://cloudinit.readthedocs.io/en/latest/topics/modules.html"},{default:e(()=>[...s[24]||(s[24]=[n("許多 user-data 模組",-1)])]),_:1}),s[26]||(s[26]=n("來配置你的實例。對於這個例子，只需使用 ",-1)),s[27]||(s[27]=a("code",null,"write_files",-1)),s[28]||(s[28]=n(" 模組在客户端創建一些測試文件，並驗證 Cloud-init 是否工作。",-1))]),s[56]||(s[56]=l(`<p>創建一個包含以下內容的用户數據文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#cloud-config</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Create two files with example content using the write_files module</span></span>
<span class="line"><span>write_files:</span></span>
<span class="line"><span> - content: |</span></span>
<span class="line"><span>    &quot;Does cloud-init work?&quot;</span></span>
<span class="line"><span>   owner: root:root</span></span>
<span class="line"><span>   permissions: &#39;0644&#39;</span></span>
<span class="line"><span>   path: /srv/foo</span></span>
<span class="line"><span> - content: |</span></span>
<span class="line"><span>   &quot;IT SURE DOES!&quot;</span></span>
<span class="line"><span>   owner: root:root</span></span>
<span class="line"><span>   permissions: &#39;0644&#39;</span></span>
<span class="line"><span>   path: /srv/bar</span></span></code></pre></div><p>除了使用 Cloud-init 提供的 <code>user-data</code> 模組製作 YAML 文件外，你還可以將其製作成一個可執行腳本供 Cloud-init 運行。</p><p>創建 <code>user-data</code> 文件後，在容器文件中添加以下行，以便在重建映像時將其複製到鏡像中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Copy the user-data file into the container image</span></span>
<span class="line"><span>COPY user-data \${WWW_DIR}/user-data</span></span></code></pre></div><p>重建鏡像，並創建和運行一個新的容器，這次使用用户數據信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Build a new image named cloud-init:03</span></span>
<span class="line"><span>podman build -f Containerfile -t cloud-init:03 .</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run a new container with this new user-data file</span></span>
<span class="line"><span>podman run --rm -p 8080:8080 -it cloud-init:03</span></span></code></pre></div><p>現在，重啓 Cloud-init 客户端，觀察 Web 服務器上的 Nginx 日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 - - [09/May/2020:23:01:51 +0000] &quot;GET /meta-data HTTP/1.1&quot; 200 63 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-&quot;</span></span>
<span class="line"><span>127.0.0.1 - - [09/May/2020:23:01:51 +0000] &quot;GET /user-data HTTP/1.1&quot; 200 298 &quot;-&quot; &quot;Cloud-Init/17.1&quot; &quot;-</span></span></code></pre></div><p>成功了！這一次，元數據和用户數據文件都被送到了 Cloud-init 客户端。</p><h3 id="驗證-cloud-init-已運行" tabindex="-1">驗證 Cloud-init 已運行 <a class="header-anchor" href="#驗證-cloud-init-已運行" aria-label="Permalink to “驗證 Cloud-init 已運行”">​</a></h3><p>從上面的日誌中，你知道 Cloud-init 在客户端主機上運行並請求元數據和用户數據文件，但它用它們做了什麼？你可以在 <code>write_files</code> 部分驗證 Cloud-init 是否寫入了你在用户數據文件中添加的文件。</p><p>在 Cloud-init 客户端上，檢查 <code>/srv/foo</code> 和 <code>/srv/bar</code> 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /srv/ &amp;&amp; ls</span></span>
<span class="line"><span>bar foo</span></span>
<span class="line"><span># cat foo</span></span>
<span class="line"><span>&quot;Does cloud-init work?&quot;</span></span>
<span class="line"><span># cat bar</span></span>
<span class="line"><span>&quot;IT SURE DOES!&quot;</span></span></code></pre></div><p>成功了！文件已經寫好了，並且有你期望的內容。</p><p>如上所述，還有很多其他模組可以用來配置主機。例如，用户數據文件可以配置成用 <code>apt</code> 添加包、複製 SSH 的 <code>authorized_keys</code>、創建用户和組、配置和運行配置管理工具等等。我在家裏的私有云中使用它來複制我的 <code>authorized_keys</code>、創建一個本地用户和組，並設置 sudo 權限。</p><h3 id="你接下來可以做什麼" tabindex="-1">你接下來可以做什麼 <a class="header-anchor" href="#你接下來可以做什麼" aria-label="Permalink to “你接下來可以做什麼”">​</a></h3><p>Cloud-init 在家庭實驗室中很有用，尤其是專注於雲技術的實驗室。本文所演示的簡單服務對於家庭實驗室來説可能並不是超級有用，但現在你已經知道 Cloud-init 是如何工作的了，你可以繼續創建一個動態服務，可以用自定義數據配置每台主機，讓家裏的私有云更類似於主流雲提供商提供的服務。</p><p>在數據源稍顯複雜的情況下，將新的物理（或虛擬）機器添加到家中的私有云中，可以像插入它們並打開它們一樣簡單。</p><hr>`,20)),a("p",null,[s[30]||(s[30]=n("via: ",-1)),t(i,{href:"https://opensource.com/article/20/5/create-simple-cloud-init-service-your-homelab"},{default:e(()=>[...s[29]||(s[29]=[n("https://opensource.com/article/20/5/create-simple-cloud-init-service-your-homelab",-1)])]),_:1})]),a("p",null,[s[35]||(s[35]=n("作者：",-1)),t(i,{href:"https://opensource.com/users/clcollins"},{default:e(()=>[...s[31]||(s[31]=[n("Chris Collins",-1)])]),_:1}),s[36]||(s[36]=n(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[32]||(s[32]=[n("lujun9972",-1)])]),_:1}),s[37]||(s[37]=n(" 譯者：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[33]||(s[33]=[n("wxy",-1)])]),_:1}),s[38]||(s[38]=n(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[34]||(s[34]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[41]||(s[41]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[39]||(s[39]=[n("LCTT",-1)])]),_:1}),s[42]||(s[42]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[40]||(s[40]=[n("Linux中國",-1)])]),_:1}),s[43]||(s[43]=n(" 榮譽推出",-1))])])}const y=p(r,[["render",c]]);export{T as __pageData,y as default};
